import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]

def attach_final(overlay):
 base=json.loads((ROOT/'headneck/content/hn04_a.json').read_text())
 def spec(n):return overlay['topics'][f'hn04-T{n:02}']
 def insert(n,i,blocks):
  after=spec(n)['after'];after[str(i)]=after.get(str(i),[])+blocks
 def note(n,i,title,text,src):
  insert(n,i,[dict(type='callout',kind='info',title=title,text=text,src=src)])
 def reconcile(n,i,text,reason,page):
  original=base[n-1]['blocks'][i]
  spec(n).setdefault('source_reconciliation',{})[str(i)]={
   'expected_text':original['text'],'text':text,'reason':reason,
   'source_part':2,'source_pdf_page':page}
