 def plate(aid,title,page,description,labels,book='lecture',plate_no=None,view=''):
  cite=(f'جزوه، بخش ۱، صفحهٔ PDF {page}؛ زیرشکل مستقل' if book=='lecture' else f'نتر، پلیت {plate_no}، ص {page} PDF؛ زیرشکل انتخابی')
  return dict(type='plate',book=book,asset=f'headneck/images/{aid}.jpeg',title=title,citation=cite,en_caption={61:'Lateral Wall of Nasal Cavity — lower illustration',63:'Medial Wall of Nasal Cavity (Nasal Septum) — lower illustration',125:'Bony and membranous labyrinths: schema'}.get(plate_no,''),view=view,fa_text=description,labels=labels,src=cite,max_h=125,min_img_h=80)
 def split(n,i,parts):
  first=parts[0]
  # The baseline frame is retained as a checked presentation override; no base JSON changes.
  spec(n)['plate_overrides'][str(i)]={k:v for k,v in first.items() if k not in ('type','book')}
  insert(n,i,parts[1:])
